pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= address(this).balance);
        Reentrant r = new Reentrant(c);
        vm.deal(address(r), amount);
        r.deposit{value: amount}();
        bool ok = r.attack(amount);
        assertTrue(ok);
    }

    receive() external payable {}
}

contract Reentrant {
    C c;
    constructor(C target) { c = target; }

    function deposit() external payable { c.deposit{value: msg.value}(); }

    function attack(uint256 amount) external returns (bool) {
        c.withdraw(amount); // triggers re-entrant withdraw below
        return true;
    }

    receive() external payable {
        if (msg.sender == address(c)) {
            // re-enter while the original withdraw is mid-flight:
            // in correct C the balance is not yet decremented,
            // in the mutant it already is, so this reverts.
            c.withdraw(c.balances(address(this)));
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    ReentrantAttacker attacker;

    function setUp() public {
        c = new C();
        attacker = new ReentrantAttacker(c);
    }

    function testFuzz_property(uint128 dRaw, uint128 a1Raw, uint128 a2Raw) public {
        uint256 d = uint256(bound(dRaw, 3, type(uint128).max));
        uint256 a1 = uint256(bound(a1Raw, 1, d - 2));
        uint256 a2 = uint256(bound(a2Raw, a1 + 1, d - a1));
        // rule: a1 < a2 and a1 + a2 <= d => a re-entrant withdraw(a2) fired during
        // withdraw(a1) must succeed and pay out a1+a2, since the reference keeps the
        // full balance until after the transfer. The mutant decrements first, so the
        // re-entrant withdraw sees only d-a1 < a2 and the whole call reverts.

        vm.deal(address(attacker), d);
        vm.prank(address(attacker));
        c.deposit{value: d}();

        attacker.arm(a2);
        bool ok;
        try attacker.attack(a1) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok && address(c).balance == d - a1 - a2);
    }
}

contract ReentrantAttacker {
    C c;
    uint256 reAmount;
    bool armed;

    constructor(C c_) {
        c = c_;
    }

    function arm(uint256 amount) external {
        reAmount = amount;
        armed = true;
    }

    function attack(uint256 amount) external {
        c.withdraw(amount);
        armed = false;
    }

    receive() external payable {
        if (armed) {
            armed = false;
            c.withdraw(reAmount);
        }
    }
}

