pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmt, uint256 withdrawAmt) public {
        depositAmt = bound(depositAmt, 1, 1e30);
        withdrawAmt = bound(withdrawAmt, 1, depositAmt);

        // adversarial re-entrant counterparty: during the ETH receipt of the
        // withdrawal payout it re-reads its own balance in c and reverts if
        // that balance has already been decremented (it must still be the
        // full deposited amount, since the reference decrements only after
        // the transfer).
        Attacker a = new Attacker(c, depositAmt);
        vm.deal(address(a), depositAmt);
        a.dep{value: depositAmt}();

        bool ok;
        vm.prank(address(a));
        try c.withdraw(withdrawAmt) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract Attacker {
    C immutable cimm;
    uint256 immutable expected;

    constructor(C _c, uint256 e) {
        cimm = _c;
        expected = e;
    }

    function dep() external payable {
        cimm.deposit{value: msg.value}();
    }

    fallback() external payable {
        if (cimm.balances(address(this)) != expected) revert();
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker atk;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 D, uint256 a1, uint256 a2, uint256 extra) public {
        D = bound(D, 2, 1e30);
        a1 = bound(a1, 1, D);
        a2 = bound(a2, 1, D);
        // force the distinguishing regime: inner re-entrant amount exceeds the
        // post-decrement balance but not the pre-decrement credited balance,
        // and the contract's forced reserve covers both payouts
        vm.assume(a1 + a2 > D);          // re-entry only succeeds if balance still D (reference)
        extra = bound(extra, a1 + a2 - D, 1e30); // reserve so both transfers in the reference succeed

        atk = new Attacker(c);
        vm.deal(address(atk), D);
        vm.prank(address(atk));
        atk.deposit();                   // balances[attacker] = D
        vm.deal(address(c), extra);      // forced reserve on the contract itself
        atk.setA2(a2);                   // re-entrant amount used inside receive()

        bool ok = atk.attack(a1);        // outer withdraw with re-entrant inner withdraw(a2)

        // Reference: outer and re-entrant withdraw both succeed, so the contract's
        // total reserve plus deposit is drained by exactly a1 + a2.
        // Mutant: balance already decremented at re-entry, require fails, everything
        // reverts, so address(c).balance stays at extra.
        assertTrue(ok && address(c).balance == D + extra - a1 - a2);
    }
}

contract Attacker {
    C c;
    uint256 reAmt;

    constructor(C _c) {
        c = _c;
    }

    function setA2(uint256 x) external {
        reAmt = x;
    }

    function deposit() external payable {
        c.deposit{value: msg.value}();
    }

    function attack(uint256 a1) external returns (bool) {
        try c.withdraw(a1) {
            return true;
        } catch {
            return false;
        }
    }

    receive() external payable {
        // re-enter withdraw during the outer transfer
        try c.withdraw(reAmt) {} catch {}
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function test(uint256 amount) public {
        require(amount > 0);
        require(address(this).balance >= amount);
        c.deposit{value: amount}();
        bool ok;
        c.withdraw(amount);
        ok = true;
        assert(ok);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function t(uint256 v) public {
        require(address(this).balance >= v);
        if (v > 0) {
            c.deposit{value: v}();
        }
        bool ok = true;
        try c.deposit{value: 0}() {
            ok = true;
        } catch {
            ok = false;
        }
        assert(!ok);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function depositThenWithdraw(uint256 amount) public {
        require(address(this).balance >= amount);
        c.deposit{value: amount}();
        uint256 balAfterDeposit = address(c).balance;
        c.withdraw(amount);
        assert(address(c).balance == balAfterDeposit - amount);
    }
}

